style.css:
@-moz-document domain("character.ai") {
/* Changer la couleur de l'arrière-plan */
    body {
        background-color: #fdf0f2 !important;
    }

    /* Changer la couleur de la barre latérale */
    .sidebar, .side-menu {
        background-color: #fadadf !important;
    }

    /* Changer la couleur de la barre en tête */
    header, .header, .top-header, .nav-bar {
        background-color: #fdf0f2 !important; /* Couleur rose */
        color: #000000 !important; /* Texte noir pour la visibilité */
    }

    /* Changer la couleur des boutons interactifs */
    button, .btn, .interactive-button {
        background-color: #ffffff !important;
        color: #000000 !important; /* Assurez-vous que le texte est visible */
        border: 1px solid #ccc !important; /* Ajoutez une bordure pour la visibilité */
    }

    /* Changer la couleur des onglets */
    .tab, .tabs, .tab-button, .active-tab {
        background-color: #ffffff !important;
        color: #000000 !important; /* Assurez-vous que le texte est visible */
    }

    /* Optionnel : Assombrir les boutons et onglets au survol */
    button:hover, .btn:hover, .interactive-button:hover, .tab:hover {
        background-color: #f0f0f0 !important;
    }
}
